1	syntax = "proto3";
2	
3	package memos.store;
4	
5	import "google/type/color.proto";
6	
7	option go_package = "gen/store";
8	
9	enum InstanceSettingKey {
10	  INSTANCE_SETTING_KEY_UNSPECIFIED = 0;
11	  // BASIC is the key for basic settings.
12	  BASIC = 1;
13	  // GENERAL is the key for general settings.
14	  GENERAL = 2;
15	  // STORAGE is the key for storage settings.
16	  STORAGE = 3;
17	  // MEMO_RELATED is the key for memo related settings.
18	  MEMO_RELATED = 4;
19	  // TAGS is the key for tag metadata.
20	  TAGS = 5;
21	  // NOTIFICATION is the key for notification transport settings.
22	  NOTIFICATION = 6;
23	  // AI is the key for AI provider settings.
24	  AI = 7;
25	}
26	
27	message InstanceSetting {
28	  InstanceSettingKey key = 1;
29	  oneof value {
30	    InstanceBasicSetting basic_setting = 2;
31	    InstanceGeneralSetting general_setting = 3;
32	    InstanceStorageSetting storage_setting = 4;
33	    InstanceMemoRelatedSetting memo_related_setting = 5;
34	    InstanceTagsSetting tags_setting = 6;
35	    InstanceNotificationSetting notification_setting = 7;
36	    InstanceAISetting ai_setting = 8;
37	  }
38	}
39	
40	message InstanceBasicSetting {
41	  // The secret key for instance. Mainly used for session management.
42	  string secret_key = 1;
43	  // The current schema version of database.
44	  string schema_version = 2;
45	}
46	
47	message InstanceGeneralSetting {
48	  // disallow_user_registration disallows user registration.
49	  bool disallow_user_registration = 2;
50	  // disallow_password_auth disallows password authentication.
51	  bool disallow_password_auth = 3;
52	  // additional_script is the additional script.
53	  string additional_script = 4;
54	  // additional_style is the additional style.
55	  string additional_style = 5;
56	  // custom_profile is the custom profile.
57	  InstanceCustomProfile custom_profile = 6;
58	  // week_start_day_offset is the week start day offset from Sunday.
59	  // 0: Sunday, 1: Monday, 2: Tuesday, 3: Wednesday, 4: Thursday, 5: Friday, 6: Saturday
60	  // Default is Sunday.
61	  int32 week_start_day_offset = 7;
62	  // disallow_change_username disallows changing username.
63	  bool disallow_change_username = 8;
64	  // disallow_change_nickname disallows changing nickname.
65	  bool disallow_change_nickname = 9;
66	}
67	
68	message InstanceCustomProfile {
69	  string title = 1;
70	  string description = 2;
71	  string logo_url = 3;
72	}
73	
74	message InstanceStorageSetting {
75	  enum StorageType {
76	    STORAGE_TYPE_UNSPECIFIED = 0;
77	    // STORAGE_TYPE_DATABASE is the database storage type.
78	    DATABASE = 1;
79	    // STORAGE_TYPE_LOCAL is the local storage type.
80	    LOCAL = 2;
81	    // STORAGE_TYPE_S3 is the S3 storage type.
82	    S3 = 3;
83	  }
84	  // storage_type is the storage type.
85	  StorageType storage_type = 1;
86	  // The template of file path.
87	  // e.g. assets/{timestamp}_{filename}
88	  string filepath_template = 2;
89	  // The max upload size in megabytes.
90	  int64 upload_size_limit_mb = 3;
91	  // The S3 config.
92	  StorageS3Config s3_config = 4;
93	}
94	
95	// Reference: https://developers.cloudflare.com/r2/examples/aws/aws-sdk-go/
96	message StorageS3Config {
97	  string access_key_id = 1;
98	  string access_key_secret = 2;
99	  string endpoint = 3;
100	  string region = 4;
101	  string bucket = 5;
102	  bool use_path_style = 6;
103	  // insecure_skip_tls_verify disables TLS certificate verification when connecting
104	  // to the S3 endpoint. Only enable this for trusted endpoints that use a self-signed
105	  // certificate; it removes protection against man-in-the-middle attacks.
106	  bool insecure_skip_tls_verify = 7;
107	}
108	
109	message InstanceMemoRelatedSetting {
110	  reserved 2;
111	  reserved "display_with_update_time";
112	  // content_length_limit is the limit of content length. Unit is byte.
113	  int32 content_length_limit = 3;
114	  // enable_double_click_edit enables editing on double click.
115	  bool enable_double_click_edit = 4;
116	  // reactions is the list of reactions.
117	  repeated string reactions = 7;
118	}
119	
120	message InstanceTagMetadata {
121	  // Optional background color for the tag label.
122	  // When unset, the default tag color is used.
123	  google.type.Color background_color = 1;
124	  // Whether memos with this tag should have their content blurred.
125	  bool blur_content = 2;
126	}
127	
128	// Active tag metadata is stored in per-user tag settings.
129	// This message remains for backward compatibility with existing clients and migrations.
130	message InstanceTagsSetting {
131	  // Map of tag name pattern to tag metadata.
132	  // Each key is treated as an anchored regular expression (^pattern$),
133	  // so a single entry like "project/.*" matches all tags under that prefix.
134	  // Exact tag names are also valid (they are trivially valid regex patterns).
135	  map<string, InstanceTagMetadata> tags = 1;
136	}
137	
138	message InstanceNotificationSetting {
139	  EmailSetting email = 1;
140	
141	  message EmailSetting {
142	    bool enabled = 1;
143	    string smtp_host = 2;
144	    int32 smtp_port = 3;
145	    string smtp_username = 4;
146	    string smtp_password = 5;
147	    string from_email = 6;
148	    string from_name = 7;
149	    string reply_to = 8;
150	    bool use_tls = 9;
151	    bool use_ssl = 10;
152	  }
153	}
154	
155	message InstanceAISetting {
156	  // providers is the list of AI provider configurations available instance-wide.
157	  repeated AIProviderConfig providers = 1;
158	
159	  // transcription is the speech-to-text feature configuration.
160	  // When unset or transcription.provider_id is empty, transcription is disabled.
161	  TranscriptionConfig transcription = 2;
162	}
163	
164	message AIProviderConfig {
165	  string id = 1;
166	  string title = 2;
167	  AIProviderType type = 3;
168	  string endpoint = 4;
169	  // api_key is write-only at the API layer and is required by the server to call providers.
170	  string api_key = 5;
171	}
172	
173	enum AIProviderType {
174	  AI_PROVIDER_TYPE_UNSPECIFIED = 0;
175	  OPENAI = 1;
176	  GEMINI = 2;
177	}
178	
179	// TranscriptionConfig configures the speech-to-text feature.
180	message TranscriptionConfig {
181	  // provider_id references an entry in InstanceAISetting.providers[].id.
182	  // Empty string means transcription is disabled.
183	  string provider_id = 1;
184	
185	  // model is the provider-specific model identifier.
186	  // Empty string falls back to the engine default.
187	  // OPENAI examples:
188	  //   - whisper-1 (legacy, lower cost)
189	  //   - gpt-4o-transcribe, gpt-4o-mini-transcribe (higher quality)
190	  //   - gpt-4o-transcribe-diarize (includes speaker labels)
191	  // GEMINI examples:
192	  //   - gemini-2.5-flash (default, multimodal call)
193	  //   - gemini-2.5-pro
194	  string model = 2;
195	
196	  // language is the default ISO 639-1 language hint sent to the provider.
197	  // Empty string lets the provider auto-detect.
198	  string language = 3;
199	
200	  // prompt is a default spelling/vocabulary hint passed to the provider.
201	  // Used as the OpenAI Whisper "prompt" parameter (a soft hint that the model
202	  // may ignore) and folded into the Gemini generation prompt as a "Context and
203	  // spelling hints" block (which the LLM will treat more literally).
204	  string prompt = 4;
205	}
